where (food.nevo_code, food.name, food.name_nl, food.name_en, food.synonyms, food.food_group, food.source_note, food.per_ml, food.state, food.cook_yield, food.units, food.kj, food.kcal, food.protein_g, food.fat_g, food.sat_fat_g, food.mufa_g, food.pufa_g, food.carbs_g, food.sugars_g, food.starch_g, food.polyols_g, food.fiber_g, food.alcohol_g, food.sodium_mg, food.deleted_at, food.source_version)
  is distinct from (excluded.nevo_code, excluded.name, excluded.name_nl, excluded.name_en, excluded.synonyms, excluded.food_group, excluded.source_note, excluded.per_ml, excluded.state, excluded.cook_yield, excluded.units, excluded.kj, excluded.kcal, excluded.protein_g, excluded.fat_g, excluded.sat_fat_g, excluded.mufa_g, excluded.pufa_g, excluded.carbs_g, excluded.sugars_g, excluded.starch_g, excluded.polyols_g, excluded.fiber_g, excluded.alcohol_g, excluded.sodium_mg, null, excluded.source_version);

-- GetIt's own shared recipes: lines pointed at the NEVO food that fits what the recipe says.
update public.recipe_line l set food_id = n.id, state = coalesce(x.state, l.state)
from (values ('Beef Sirloin Top', 1400, null), ('Turkey Breast Meat+Skin', 1936, null), ('Fish Tuna Skipjack', 1590, 'raw'), ('Lettuce Green Leaf', 2346, null)) as x(old_name, code, state),
  public.food o, public.food n, public.recipe r
where l.food_id = o.id and o.owner_id is null and o.nevo_code is null and o.name = x.old_name
  and n.nevo_code = x.code and r.id = l.recipe_id and r.owner_id is null;

