-- Everything that pointed at a replaced food points at its replacement. Rows
-- are updated in place, so each device's next sync brings the change.
update public.recipe_line l set food_id = f.replaced_by
  from public.food f where l.food_id = f.id and f.replaced_by is not null;
update public.food_log l set food_id = f.replaced_by
  from public.food f where l.food_id = f.id and f.replaced_by is not null;
update public.meal_plan_slot s set food_id = f.replaced_by
  from public.food f where s.food_id = f.id and f.replaced_by is not null;
update public.shopping_entry e set food_id = f.replaced_by
  from public.food f where e.food_id = f.id and f.replaced_by is not null;

do $$
declare
  r record;
  twin record;
begin
  -- The cupboard holds one row per food per household. Where it already has
  -- the replacement, the old row's amount is added to it and the old row is
  -- taken out; otherwise the old row simply moves over.
  for r in
    select s.*, f.replaced_by as new_food from public.stock s join public.food f on f.id = s.food_id
    where f.replaced_by is not null
  loop
    select * into twin from public.stock where household_id = r.household_id and food_id = r.new_food;
    if not found then
      update public.stock set food_id = r.new_food where id = r.id;
    elsif r.deleted_at is null then
      update public.stock
         set grams_on_hand = least(9999999, (case when twin.deleted_at is null then twin.grams_on_hand else 0 end) + r.grams_on_hand),
             deleted_at = null, unit = null, unit_qty = null
       where id = twin.id;
      update public.stock set deleted_at = now() where id = r.id;
    end if;
  end loop;

  -- A tick on a planned item is keyed by the food's id; it follows the food,
  -- unless the household has already ticked the replacement.
  for r in
    select e.id, e.household_id, f.replaced_by::text as new_key from public.shopping_entry e
    join public.food f on e.plan_key = f.id::text
    where f.replaced_by is not null and e.deleted_at is null
  loop
    if exists (select 1 from public.shopping_entry
               where household_id = r.household_id and plan_key = r.new_key and deleted_at is null) then
      update public.shopping_entry set deleted_at = now() where id = r.id;
    else
      update public.shopping_entry set plan_key = r.new_key where id = r.id;
    end if;
  end loop;

  -- A module's records and the profile's books can hold a food's id anywhere
  -- in them. Ids are unique, so the text of one never matches anything else.
  for r in select id::text as old_id, replaced_by::text as new_id from public.food where replaced_by is not null loop
    update public.module_record set data = replace(data::text, r.old_id, r.new_id)::jsonb
     where data::text like '%' || r.old_id || '%';
    update public.profile set settings = replace(settings::text, r.old_id, r.new_id)::jsonb
     where settings is not null and settings::text like '%' || r.old_id || '%';
  end loop;
end $$;

create unique index if not exists food_global_name_idx on public.food (lower(name))
  where owner_id is null and deleted_at is null;

-- 4: late arrivals ---------------------------------------------------------------------------
-- A phone that was offline when the catalogue changed may still send a meal,
-- an ingredient or a tick for an old food. It lands on the replacement.
create or replace function private.replacement_food(fid uuid)
returns uuid language sql stable security definer set search_path = '' as $$
  -- At most a few steps: a replacement that is itself replaced later.
  with recursive chain(id, depth) as (
    select replaced_by, 1 from public.food where id = fid and replaced_by is not null
    union all
    select f.replaced_by, c.depth + 1 from chain c join public.food f on f.id = c.id
    where f.replaced_by is not null and c.depth < 5
  )
  select id from chain order by depth desc limit 1
$$;
revoke all on function private.replacement_food(uuid) from public, anon;
grant execute on function private.replacement_food(uuid) to authenticated, service_role;

create or replace function private.food_redirect()
returns trigger language plpgsql set search_path = '' as $$
declare
  next_id uuid;
begin
  if new.food_id is not null then
    next_id := private.replacement_food(new.food_id);
    if next_id is not null then new.food_id := next_id; end if;
  end if;
  return new;
end $$;

create or replace function private.plan_key_redirect()
returns trigger language plpgsql set search_path = '' as $$
declare
  next_id uuid;
begin
  if new.plan_key ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    next_id := private.replacement_food(new.plan_key::uuid);
    if next_id is not null then new.plan_key := next_id::text; end if;
  end if;
  return new;
end $$;

-- Named to run before the sharing guard on recipe lines (triggers of one
-- kind run in name order), so the guard sees the food the line ends up with.
drop trigger if exists a_food_redirect on public.recipe_line;
create trigger a_food_redirect before insert or update of food_id on public.recipe_line
  for each row execute function private.food_redirect();
drop trigger if exists a_food_redirect on public.food_log;
create trigger a_food_redirect before insert or update of food_id on public.food_log
  for each row execute function private.food_redirect();
drop trigger if exists a_food_redirect on public.meal_plan_slot;
create trigger a_food_redirect before insert or update of food_id on public.meal_plan_slot
  for each row execute function private.food_redirect();
drop trigger if exists a_food_redirect on public.shopping_entry;
create trigger a_food_redirect before insert or update of food_id on public.shopping_entry
  for each row execute function private.food_redirect();
drop trigger if exists a_plan_key_redirect on public.shopping_entry;
create trigger a_plan_key_redirect before insert or update of plan_key on public.shopping_entry
  for each row execute function private.plan_key_redirect();
drop trigger if exists a_food_redirect on public.stock;
create trigger a_food_redirect before insert or update of food_id on public.stock
  for each row execute function private.food_redirect();

-- 5: ready meals ------------------------------------------------------------------------------
alter table public.recipe drop constraint if exists recipe_role_check;
alter table public.recipe add constraint recipe_role_check
  check (role in ('breakfast','lunch','dinner','snack','shake','egg_meal','main','kwark','ready'));

-- 6: no default meal slots ----------------------------------------------------------------------
update public.module set default_settings = '{}'::jsonb where key = 'nutrition' and default_settings <> '{}'::jsonb;
